// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    SigMaker maker;

    function setUp() public { c = new PuttyV2("", 0, address(this)); maker = new SigMaker(); }

    function testFuzz_property(address to, address to2, uint256 premium, uint256 strike) public {
        vm.assume(to != address(0));
        vm.assume(to2 != address(0));

        PuttyV2.Order memory o;
        o.maker = address(maker);
        o.isCall = false;
        o.isLong = true;
        o.baseAsset = address(maker);
        o.strike = strike;
        o.premium = premium;
        o.duration = 1 days;
        o.expiration = block.timestamp + 1 days;
        o.whitelist = new address[](0);
        o.floorTokens = new address[](0);
        o.erc20Assets = new PuttyV2.ERC20Asset[](0);
        o.erc721Assets = new PuttyV2.ERC721Asset[](0);

        bytes memory sig = new bytes(65); // invalid ECDSA -> falls back to maker's ERC-1271 check
        uint256[] memory floorIds = new uint256[](0);

        c.fillOrder(o, sig, floorIds);

        uint256 positionId = uint256(c.hashOppositeOrder(o)); // long position NFT minted to msg.sender

        // First transfer by the current owner (test contract) to `to`
        c.transferFrom(address(this), to, positionId);

        // General rule: the new owner can transfer the token again.
        bool ok;
        vm.prank(to);
        try c.transferFrom(to, to2, positionId) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract SigMaker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e; // IERC1271.isValidSignature.selector
    }

    fallback() external payable {}
}
